#include "geometry/triangle.hpp"

#include <cmath>
#include <stdexcept>

namespace geometry {

Triangle::Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {
    if (a <= 0 || b <= 0 || c <= 0) {
        throw std::invalid_argument("sides must be positive");
    }
    if (a + b <= c || a + c <= b || b + c <= a) {
        throw std::invalid_argument("cannot form a triangle with given sides");
    }
}

std::string Triangle::name() const { return "triangle"; }

double Triangle::area() const {
    double s = (a_ + b_ + c_) / 2.0;
    return std::sqrt(s * (s - a_) * (s - b_) * (s - c_));
}

}  // namespace geometry
