#ifndef RINGBUF_H
#define RINGBUF_H

#include <stdbool.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

/* 固定容量的環形緩衝區：滿了再放會蓋掉最舊的元素。 */
typedef struct {
    double *data;
    size_t capacity;
    size_t head;   /* 下一個要寫入的位置 */
    size_t count;  /* 目前的元素個數 */
} RingBuf;

/* 配置容量為 capacity 的緩衝區；capacity 為 0 或記憶體不足時回傳 false。 */
bool rb_init(RingBuf *rb, size_t capacity);
void rb_free(RingBuf *rb);

/* 放入一個值（滿了就蓋掉最舊的）。 */
void rb_push(RingBuf *rb, double value);

/* 取出最舊的值放到 *out；空的時回傳 false。 */
bool rb_pop(RingBuf *rb, double *out);

/* 查看最舊的值放到 *out 但不取出；空的時回傳 false。 */
bool rb_peek_oldest(const RingBuf *rb, double *out);

/* 清空所有元素（容量不變，之後可以繼續放）。 */
void rb_clear(RingBuf *rb);

size_t rb_size(const RingBuf *rb);
bool rb_is_full(const RingBuf *rb);

/* 目前所有元素的平均；空的時回傳 0。 */
double rb_mean(const RingBuf *rb);

#ifdef __cplusplus
}
#endif

#endif /* RINGBUF_H */
```

### 檔案：src/ringbuf.c
```c
#include "ringbuf.h"

#include <stdlib.h>

bool rb_init(RingBuf *rb, size_t capacity) {
    if (capacity == 0) {
        return false;
    }
    rb->data = malloc(capacity * sizeof(double));
    if (rb->data == NULL) {
        return false;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->count = 0;
    return true;
}

void rb_free(RingBuf *rb) {
    free(rb->data);
    rb->data = NULL;
    rb->capacity = rb->head = rb->count = 0;
}

void rb_push(RingBuf *rb, double value) {
    rb->data[rb->head] = value;
    rb->head = (rb->head + 1) % rb->capacity;
    if (rb->count < rb->capacity) {
        rb->count++;
    }
}

bool rb_pop(RingBuf *rb, double *out) {
    if (rb->count == 0) {
        return false;
    }
    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
    *out = rb->data[tail];
    rb->count--;
    return true;
}

bool rb_peek_oldest(const RingBuf *rb, double *out) {
    if (rb->count == 0) {
        return false;
    }
    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
    *out = rb->data[tail];
    return true;
}

void rb_clear(RingBuf *rb) {
    rb->head = 0;
    rb->count = 0;
}

size_t rb_size(const RingBuf *rb) { return rb->count; }

bool rb_is_full(const RingBuf *rb) { return rb->count == rb->capacity; }

double rb_mean(const RingBuf *rb) {
    if (rb->count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
    for (size_t i = 0; i < rb->count; i++) {
        sum += rb->data[(tail + i) % rb->capacity];
    }
    return sum / (double)rb->count;
}
